class PlatformInfo:
    """平台抽象层: 隔离 EL/Debian 发行版差异。

    业务逻辑通过 self.platform.get("key") 访问平台特定值,
    无需在每个方法中写 if pkg_mgr == "apt" / elif in ("dnf","yum")。

    模板值中的 {ver}, {pkg_mgr}, {domain}, {prefix} 在 resolve() 时填充。

    Usage:
        platform = PlatformInfo(pkg_mgr="dnf")
        svc = platform.get("php_fpm_service")           # → "php-fpm"
        svc = platform.get("php_fpm_service", ver="8.4") # → "php-fpm" (EL 不含版本)

        platform = PlatformInfo(pkg_mgr="apt")
        svc = platform.get("php_fpm_service", ver="8.4") # → "php8.4-fpm"
    """

    def __init__(self, pkg_mgr: str) -> None:
        self.pkg_mgr = pkg_mgr
        if pkg_mgr in ("dnf", "yum"):
            self.family = "el"
        else:
            self.family = "debian"
        self._reg: dict = _PLATFORM_REGISTRY[self.family]

    @property
    def is_el(self) -> bool:
        return self.family == "el"

    @property
    def is_debian(self) -> bool:
        return self.family == "debian"

    def get(self, key: str, **kwargs: str) -> Any:
        """获取平台值, 自动填充模板变量。

        kwargs 传入模板变量: ver="8.4", pkg_mgr="dnf", domain="example.com"
        """
        val = self._reg.get(key)
        if val is None:
            return None
        kwargs.setdefault("pkg_mgr", self.pkg_mgr)
        return self._resolve(val, kwargs)

    def _resolve(self, val: Any, ctx: dict) -> Any:
        """递归填充模板变量 {ver}, {pkg_mgr} 等。

        未提供的模板变量自动替换为空字符串, 避免残留 {ver} 等
        字面文本出现在文件路径或命令参数中。
        """
        if isinstance(val, str):
            if '{' not in val:
                return val
            # 缺失的模板变量→空字符串, 不残留 {xxx}
            try:
                return val.format(**ctx)
            except KeyError:
                # 回退: 逐个替换已知变量, 未知的替换为空
                result = val
                for k, v in ctx.items():
                    result = result.replace('{' + k + '}', str(v))
                # 清理残留的 {xxx} 模板
                result = re.sub(r'\{[a-z_]+\}', '', result)
                return result
        if isinstance(val, list):
            return [self._resolve(item, ctx) for item in val]
        if isinstance(val, dict):
            return {k: self._resolve(v, ctx) for k, v in val.items()}
        return val


# ---------------------------------------------------------------------------
# 多语言支持 (V3.0.5)
# ---------------------------------------------------------------------------
# 运行时优先级(高→低):
#   持久配置文件 /root/.wp_ssl_lang > WP_LANG 环境变量
#   > LANG > LC_ALL > LANGUAGE > 默认英文
# --lang CLI 参数通过写入持久配置文件间接生效 (首次使用后永久保存)。
# 注意: 模块加载阶段 (main() 之前) _LANG 由 _detect_lang() 从配置文件/
#       环境变量决定, --lang 参数此时尚未解析, 故极少数初始化阶段消息
#       可能使用配置文件/环境变量语言而非 --lang 指定语言。
# CLI 示例  : sudo python3 wp_ssl_bootstrap.py --lang en deploy ...
#   首次指定后，语言偏好自动写入 /root/.wp_ssl_lang，后续无需重复指定。
# 环境变量  : WP_LANG=en  强制英文；WP_LANG=zh  强制中文
# ---------------------------------------------------------------------------
_LANG_CONFIG_FILE = Path("/root/.wp_ssl_lang")


def _write_lang_file(chosen: str, env_at_choice: str = "") -> None:
    """Atomically write language config with 0600 permissions.

    File format: "chosen:env_at_choice"  (e.g. "zh:en")
    env_at_choice defaults to the current system language when not supplied.

    Falls back to direct (non-atomic) write if rename fails,
    ensuring the language preference is never silently lost.
    """
    _env = env_at_choice if env_at_choice in ("zh", "en") else _env_lang()
    content = f"{chosen}:{_env}"
    _bytes = content.encode("utf-8")
    tmp = _LANG_CONFIG_FILE.with_name(_LANG_CONFIG_FILE.name + ".tmp")
    try:
        _write_bytes_to_fd(str(tmp), _bytes, 0o600)
        os.replace(str(tmp), str(_LANG_CONFIG_FILE))
        return  # atomic write succeeded
    except OSError as _aw_err:
        # [V3.2.111] FIX-18: logging 可能在模块加载时尚未 basicConfig,
        # 使用 getLogger 避免 "No handlers could be found" 警告
        try:
            logging.debug("[_write_lang_file] atomic write failed, falling back: %s", _aw_err)
        except Exception:
            pass  # logger not ready yet
    finally:
        # Always clean up tmp (no-op if os.replace already consumed it)
        # [V3.0.9] S1: missing_ok=True 需要 Python 3.8+; 改写以兼容 3.6
        # [V3.2.12] P2-12: 合并两个等效的 except 分支
        # [V3.2.90] B-8: 缩窄异常捕获范围, 仅忽略 FileNotFoundError
        # (文件已被 os.replace 消费), 不掩盖 PermissionError 等真实错误
        try:
            tmp.unlink()
        except FileNotFoundError:
            pass
    # Fallback: direct write (non-atomic but functional)
    try:
        _write_bytes_to_fd(str(_LANG_CONFIG_FILE), _bytes, 0o600)
    except OSError as _fb_e:
        # [V3.2.5] A-14: 记录 fallback 写入失败, 便于排查
        # [PATCH-144 R-1] 模块加载阶段 logging 可能未初始化, 需保护
        try:
            logging.warning(t("warn_r_1_write_lang_file_fallback_failed"), _fb_e)
        except Exception as _exc_178:
            logging.debug("[PATCH-276] _write_bytes_to_fd: %s", _exc_178)


def _write_bytes_to_fd(path: str, data: bytes, mode: int = 0o600,
                       soft_fsync: bool = False) -> None:
    """底层原子写入: os.open -> write -> fsync -> close，权限从创建瞬间生效。

    [V3.2.114] R5: 提取自 _write_lang_file / _safe_write_file / atomic_write
    三处重复的 fd 操作模式，统一为单一事实来源。

    Args:
        soft_fsync: True 时 fsync 失败静默降级 (保持 atomic_write 旧版行为)。
    """
    # [PATCH-144 S-1] O_NOFOLLOW: 拒绝写入符号链接目标, 防止
    # 攻击者通过 symlink 覆盖 /etc/shadow 等敏感文件。
    # getattr 兼容无 O_NOFOLLOW 的平台 (回退为 0, 即不生效)。
    # [PATCH-252 FIX-4] 当 O_NOFOLLOW 不可用时输出一次性 WARNING,
    # 与 atomic_write L9131 的降级提示对齐, 防止符号链接保护
    # 在整个底层写入函数上静默失效而运维完全不知情。
    _o_nofollow = getattr(os, "O_NOFOLLOW", 0)
    if not _o_nofollow and not getattr(_write_bytes_to_fd,
                                        '_nofollow_warned', False):
        _write_bytes_to_fd._nofollow_warned = True
        try:
            # [PATCH-283B FIX-P2-5] 升级为 ERROR 级别, 使运维人员无法忽视。
            # O_NOFOLLOW 缺失意味着所有底层写入均无符号链接保护,
            # 攻击者可通过 symlink 覆盖任意文件 (CVE-2025-68146 同类风险)。
            logging.error(t("warn_patch_252_fix_4_nofollow_not_available_on_this"))
        except Exception:
            pass  # logging may not be ready during module load
    fd = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_TRUNC
                 | _o_nofollow, mode)
    try:
        # [PATCH-CRIT-8] os.open(mode) 受 umask 影响: mode & ~umask。
        # 例如 mode=0o644 + umask=0o077 → 实际 0o600, nginx worker 无法读取。
        # fchmod 显式设置精确权限, 不受 umask 干扰。
        os.fchmod(fd, mode)
        os.write(fd, data)
        if soft_fsync:
            try:
                os.fsync(fd)
            except OSError:
                pass  # 降级: fsync 失败不阻断, 保持旧版行为 [V3.2.27] BUG-1
        else:
            os.fsync(fd)
    finally:
        os.close(fd)


# [PATCH-284] 原子写入: write-to-temp → fsync → os.replace。
# 替代 _write_bytes_to_fd 直接写入最终文件的模式, 防止
# SIGKILL/断电时 O_TRUNC 后未完成写入导致文件截断为空。
# 适用于 APT 源、GPG 密钥、systemd 单元等不可丢失的配置文件。
def _write_bytes_atomic(path: str, data: bytes, mode: int = 0o600,
                        soft_fsync: bool = False) -> None:
    """原子写入: 先写同目录临时文件, fsync 后 rename 替换目标。

    与 _write_bytes_to_fd 的区别:
      - _write_bytes_to_fd: O_TRUNC 就地写入, 中途崩溃 → 文件截断
      - _write_bytes_atomic: temp + rename, 中途崩溃 → 旧文件完整保留

    [PATCH-284] 新增。用于所有直接写入最终目标文件的场景。
    """
    _dir = os.path.dirname(path) or "."
    _o_nofollow = getattr(os, "O_NOFOLLOW", 0)
    # 检查目标是否为符号链接 — 与 _write_bytes_to_fd 保持一致
    if _o_nofollow:
        try:
            _chk_fd = os.open(path, os.O_RDONLY | _o_nofollow)
            os.close(_chk_fd)
        except OSError as _e:
            import errno as _errno_284
            if _e.errno == _errno_284.ELOOP:
                logging.warning(
                    "[PATCH-284] Refusing atomic write to symlink: %s", path)
                return
            # 文件不存在 (ENOENT) 是正常的 — 首次创建
            if _e.errno != _errno_284.ENOENT:
                raise
    # 临时文件在同一目录, 确保同一文件系统 (rename 原子性要求)
    fd = -1
    tmp_path = ""
    try:
        fd, tmp_path = tempfile.mkstemp(
            prefix=".aw_", suffix=".tmp", dir=_dir)
        os.fchmod(fd, mode)
        os.write(fd, data)
        if soft_fsync:
            try:
                os.fsync(fd)
            except OSError:
                pass
        else:
            os.fsync(fd)
        os.close(fd)
        fd = -1
        os.replace(tmp_path, path)
        tmp_path = ""  # replace 成功, 无需清理
    finally:
        if fd >= 0:
            try:
                os.close(fd)
            except OSError:
                pass
        if tmp_path:
            try:
                os.unlink(tmp_path)
            except OSError:
                pass


def _safe_chmod(path, mode: int) -> None:
    """TOCTOU-safe chmod: open with O_NOFOLLOW then fchmod on the fd.

    [PATCH-283C] 替代 islink()+chmod() 的 check-then-act 模式。
    如果 path 是符号链接, O_NOFOLLOW 会导致 ELOOP, chmod 被跳过。
    如果 O_NOFOLLOW 不可用则降级为普通 chmod (保持旧行为)。
    对目录同样有效 (O_RDONLY open on dir is allowed on Linux)。
    """
    _nofollow = getattr(os, "O_NOFOLLOW", 0)
    try:
        _fd = os.open(str(path), os.O_RDONLY | _nofollow)
        try:
            os.fchmod(_fd, mode)
        finally:
            os.close(_fd)
    except OSError:
        pass  # symlink (ELOOP), permission error, or missing file


def _sd_escape(path: str) -> str:
    """转义路径使其可安全用于 systemd unit ExecStart= 的双引号参数。

    提升至模块级以便 setup_systemd() 与 setup_wp_cron_timer() 共用。
    [V3.2.43] FIX-7: 原为 setup_wp_cron_timer() 内嵌函数，导致
    setup_systemd() 无法访问，ExecStart 路径缺少 % / $ 转义。

    转义规则 (systemd ExecStart= 双引号上下文):
      \\  ->  \\\\   (反斜杠自身)
      "  ->  \\"   (闭合引号)
      %  ->  %%   (systemd specifier, 如 %n %i)
      $  ->  $$   (systemd 环境变量展开, v219+)

    [V3.2.90] B-6: '+' 字符无需转义 —— systemd ExecStart= 双引号
    上下文中 '+' 无特殊含义（仅裸 ExecStart=+ 有提权语义, 不影响
    双引号内参数）。domain 白名单 [a-z0-9.-] 不含 '+', email 中的
    '+' (如 user+tag@example.com) 在双引号内直接传递即可。
    """
    # [V3.2.98] FIX-D1 (§4.2): 增加换行符转义 (防御性编程)。
    # 当前所有调用方的输入值白名单校验保证不含换行符,
    # 但显式转义可防止未来新调用方引入未校验输入。
    # [V3.2.112] DEBT-1: 替换顺序不可调换 —— 反斜杠必须最先处理,
    # 否则后续步骤生成的转义反斜杠会被二次替换。例如:
    #   若先处理 " → \"，再处理 \ → \\，则 \" 变成 \\"（错误）。
    #   正确顺序: 先 \ → \\，再 " → \"，最终 \" 不被二次处理。
    # [V3.2.113] PATCH-6: 换行符从静默替换改为拒绝。
    # 所有调用方的输入已通过白名单校验 (不含换行符),
    # 若意外传入则说明上游校验被绕过, 应立即暴露而非静默掩盖。
    # [P125-4] 补充 NUL (\x00) 检测: systemd unit 中 NUL 可截断字符串,
    # 上游白名单已保护, 此为纵深防御。
    if '\n' in path or '\r' in path or '\x00' in path:
        raise ValueError(
            "_sd_escape: input contains newline/carriage-return/NUL characters; "
            "this indicates an upstream validation bypass. "
            "Input (repr): %r" % path
        )
    # [PATCH-CRIT-4] 拒绝反引号: systemd ExecStart 双引号上下文中反引号本身
    # 无特殊含义, 但若 systemd 版本或配置意外经过 shell 层 (如 Type=notify
    # 的某些实现), 反引号会触发命令替换。当前所有调用方输入已通过白名单校验
    # (域名 [a-z0-9.-] / email 标准格式), 不应包含反引号; 此处为纵深防御。
    if "`" in path:
        raise ValueError(
            "_sd_escape: input contains backtick character; "
            "this indicates an upstream validation bypass. "
            "Input (repr): %r" % path
        )
    return (path
            .replace('\\', '\\\\')
            .replace('"', '\\"')
            .replace('%', '%%')
            .replace('$', '$$'))


# ---------------------------------------------------------------------------
# 共享域名编码函数 (V3.2.121)
# ---------------------------------------------------------------------------

# ---------------------------------------------------------------------------
# [PATCH-146 P0-1] 密码字符集白名单 — 单一事实来源
# ---------------------------------------------------------------------------
# 覆盖: 全局密码文件 / --db-root-pass / wp-config.php 恢复 /
#        _mysql_escape_value 纵深防御 / backup 密码加载 / db-optimize .cnf。
# 修改此正则时, 同步审查 _mysql_escape_value / _create_defaults_file 转义。
# [AUDIT BUG-01] 移除 ^$ 锚点, 配合 fullmatch 使用, 消除 \n 绕过风险
_RE_SAFE_PASSWORD = re.compile(r'[a-zA-Z0-9!@#$%^&*()_+=.-]+')


def _is_safe_password(value: str) -> bool:
    """校验密码是否在安全字符集白名单内。

    [PATCH-146 P0-1] 7处重复 re.fullmatch 的单一事实来源。
    空字符串返回 False。
    """
    return bool(value) and bool(_RE_SAFE_PASSWORD.fullmatch(value))


# [PATCH-146 P0-3] 安全密码生成 — 单一事实来源
_AUTOGEN_PASSWORD_CHARS = string.ascii_letters + string.digits


def _generate_secure_password(length: int = 48) -> str:
    """生成密码学安全的随机密码 (纯字母数字)。

    [PATCH-146 P0-3] 3处重复 secrets.choice 循环的单一事实来源。
    [PATCH-276 FIX-DB1] 默认长度 32→48: 62^48 ≈ 2^286 bits 熵,
    超过 OWASP 推荐的 256 bits。纯字母数字字符集避免 MySQL .cnf /
    SQL 字面量 / shell 转义等场景的特殊字符问题。
    """
    return ''.join(secrets.choice(_AUTOGEN_PASSWORD_CHARS) for _ in range(length))


# [V3.2.121] FIX-4: 从 SiteConfig.__init__ 和 _nginx_safe_name() 两处
# 独立维护的编码逻辑中提取为单一事实来源。修改编码规则时只需改此一处。
#
# 编码规则 (三步无歧义, 顺序不可调换):
#   1. _ → _u  (先转义 _ 自身, 防止后续步骤引入歧义)
#   2. . → _d  (域名分隔符)
#   3. - → _h  (连字符)
#
# 数字开头时加 wp_ 前缀 (Nginx 变量 / MySQL 标识符安全)。
# ---------------------------------------------------------------------------


def _encode_domain_id(domain: str) -> str:
    """将域名编码为安全标识符 (Nginx zone / DB name / systemd prefix)。

    [V3.2.121] FIX-4: SiteConfig.__init__ 和 _nginx_safe_name() 的
    单一事实来源, 消除两处独立维护的编码逻辑分歧风险。
    """
    encoded = (
        domain
        .replace('_', '_u')
        .replace('.', '_d')
        .replace('-', '_h')
    )
    if encoded and encoded[0].isdigit():
        encoded = 'wp_' + encoded
    return encoded


def _has_reusable_cert(domain: str) -> bool:
    """[PATCH-227 FIX-2] 检测域名是否有可复用的有效 SSL 证书 (>7天)。

    用于交互向导和 CLI 参数校验: 有效证书存在时跳过邮箱要求,
    因为不需要签发新证书。

    [PATCH-228 FIX-1] 增加 SAN 域名匹配校验:
    证书文件可能因 certbot --cert-name 重命名而路径匹配但 SAN 不含
    当前域名。必须同时满足: 文件存在 + 有效期 >7天 + SAN 包含域名。
    任何步骤失败 → 返回 False (安全侧倒, 继续要求邮箱)。
    """
    _cert_228 = Path("/etc/letsencrypt/live/%s/fullchain.pem" % domain)
    if not _cert_228.exists():
        return False
    try:
        # 有效期检查
        _r_chk = subprocess.run(
            ["openssl", "x509", "-checkend", str(7 * 86400),
             "-noout", "-in", str(_cert_228)],
            stdout=subprocess.PIPE, stderr=subprocess.PIPE,
            timeout=5, check=False)
        if _r_chk.returncode != 0:
            return False
        # SAN 域名匹配检查
        _r_san = subprocess.run(
            ["openssl", "x509", "-noout", "-text",
             "-in", str(_cert_228)],
            stdout=subprocess.PIPE, stderr=subprocess.PIPE,
            encoding="utf-8", errors="replace",
            timeout=5, check=False)
        if _r_san.returncode != 0:
            return False
        _san_domains = set()
        for _line in _r_san.stdout.splitlines():
            _line = _line.strip()
            if _line.startswith("DNS:") or ", DNS:" in _line:
                for _part in _line.split(","):
                    _part = _part.strip()
                    if _part.startswith("DNS:"):
                        _d = _part[4:].strip()
                        if _d:
                            _san_domains.add(_d.lower())
        _domain_lower = domain.lower()
        if _domain_lower in _san_domains:
            return True
        # [PATCH-234 FIX-1] Wildcard certificate matching:
        # *.example.com covers blog.example.com but not example.com itself.
        # Only match if domain has at least one subdomain level above the wildcard.
        _parts = _domain_lower.split(".", 1)
        if len(_parts) == 2 and _parts[1]:
            _wildcard = "*." + _parts[1]
            if _wildcard in _san_domains:
                return True
        return False
    except Exception:
        return False


def _get_cert_issuer_cn(cert_path: str) -> str:
    """[PATCH-282] 从证书文件提取签发商 CN (模块级, 供无 self 的上下文使用)"""
    try:
        _r = subprocess.run(
            ["openssl", "x509", "-noout", "-issuer", "-in", cert_path],
            stdout=subprocess.PIPE, stderr=subprocess.DEVNULL,
            encoding="utf-8", timeout=5, check=False)
        if _r.returncode == 0 and _r.stdout:
            _m = re.search(r'CN\s*=\s*(.+?)(?:,|$)', _r.stdout)
            if _m:
                return _m.group(1).strip()
    except Exception:
        pass
    return ""


def _detect_cert_lifetime_days(cert_path: str) -> int:
    """[PATCH-277] 检测证书总有效期 (Not After - Not Before), 单位: 天。

    用于判断 CA 签发的是 90 天 / 47 天 / 6 天证书, 动态调整
    systemd timer 续期频率。

    Returns:
        证书总有效期天数。探测失败返回 0。
    """
    try:
        # openssl x509 -dates 输出格式:
        #   notBefore=Mar  1 00:00:00 2025 GMT
        #   notAfter=May 30 23:59:59 2025 GMT
        _r = subprocess.run(
            ["openssl", "x509", "-noout", "-dates", "-in", cert_path],
            stdout=subprocess.PIPE, stderr=subprocess.DEVNULL,
            encoding="utf-8", errors="replace",
            timeout=10, check=False,
        )
        if _r.returncode != 0:
            return 0
        _not_before = ""
        _not_after = ""
        for _line in _r.stdout.splitlines():
            _line = _line.strip()
            if _line.startswith("notBefore="):
                _nb_parts = _line.split("=", 1)
                _not_before = _nb_parts[1].strip() if len(_nb_parts) > 1 else ""  # [PATCH-283 FIX-P2-1a]
            elif _line.startswith("notAfter="):
                _na_parts = _line.split("=", 1)
                _not_after = _na_parts[1].strip() if len(_na_parts) > 1 else ""  # [PATCH-283 FIX-P2-1a]
        if not _not_before or not _not_after:
            return 0
        # 解析 openssl 日期格式: "Mar  1 00:00:00 2025 GMT"
        from datetime import datetime as _dt_277
        _fmt = "%b %d %H:%M:%S %Y %Z"
        # 处理月份后的双空格: "Mar  1" → "Mar 1"
        _not_before = re.sub(r'\s+', ' ', _not_before)
        _not_after = re.sub(r'\s+', ' ', _not_after)
        _dt_before = _dt_277.strptime(_not_before, _fmt)
        _dt_after = _dt_277.strptime(_not_after, _fmt)
        _delta = (_dt_after - _dt_before).days
        return max(0, _delta)
    except Exception:
        return 0


def _determine_renewal_schedule(lifetime_days: int) -> tuple:
    """[PATCH-277] 根据证书有效期动态确定 systemd timer 调度策略。

    参考 Let's Encrypt 短寿命证书计划 (2027-02: 47 天, 2028-02: 6 天)
    和 certbot ARI (ACME Renewal Information) 行为:
      - certbot 在证书剩余 1/3 生命周期时尝试续期
      - timer 触发频率应确保在续期窗口内至少有 2 次重试机会

    Returns:
        (on_calendar, randomized_delay, description) 三元组。
        lifetime_days == 0 时返回保守的每日策略。
    """
    if lifetime_days <= 0:
        # 未知有效期: 保守的每日策略
        return ("daily", "12h",
                "unknown lifetime → daily (conservative)")

    if lifetime_days <= 10:
        # 6 天证书 (LE 2028+ 计划): 每 4 小时, 随机偏移 1h
        # 续期窗口 ≈ 2 天 (1/3 × 6), 4h 间隔确保窗口内 ≥12 次重试
        return ("*-*-* 0/4:00:00", "1h",
                "%dd cert → every 4h" % lifetime_days)

    if lifetime_days <= 30:
        # 14-30 天证书: 每 8 小时, 随机偏移 2h
        return ("*-*-* 0/8:00:00", "2h",
                "%dd cert → every 8h" % lifetime_days)

    if lifetime_days <= 50:
        # 47 天证书 (LE 2027+ 计划): 每 12 小时, 随机偏移 3h
        # 续期窗口 ≈ 15 天, 12h 间隔确保窗口内 ≥30 次重试
        return ("*-*-* 0/12:00:00", "3h",
                "%dd cert → every 12h" % lifetime_days)

    # 90 天证书 (当前 LE 标准): 每天, 随机偏移 12h
    return ("daily", "12h",
            "%dd cert → daily" % lifetime_days)


# ---------------------------------------------------------------------------
# 共享转义/反转义工具 (V3.2.117)
# ---------------------------------------------------------------------------
# 设计说明:
#   从 6 处内联 .replace() 链提取而来, 消除重复代码。
#   _sd_escape() 因其 systemd 特有的 %→%% / $→$$ 规则保持独立。
#
# 替换顺序不可调换 —— 反斜杠必须最先处理, 否则后续步骤生成的
# 转义反斜杠会被二次替换 (与 _sd_escape 同理, 参见 V3.2.112 DEBT-1)。
# ---------------------------------------------------------------------------


def _escape_single_quoted(value: str) -> str:
    """转义字符串使其可安全嵌入单引号包裹的上下文 (PHP define / SQL 字面量)。

    [V3.2.117] 提取自 update_wp_config / _mysql_escape_value / _purge_site_data
    三处重复的 chr(92)/chr(39) 替换链, 统一为单一事实来源。

    转义规则:
      \\  →  \\\\  (反斜杠自身, 必须最先处理)
      '   →  \\'  (闭合引号)
    """
    return value.replace(chr(92), chr(92) * 2).replace(chr(39), chr(92) + chr(39))


def _escape_double_quoted(value: str, extra_chars: str = "") -> str:
    """转义字符串使其可安全嵌入双引号包裹的上下文 (.cnf / EnvironmentFile)。

    [V3.2.117] 提取自 _create_defaults_file (MySQL .cnf 密码转义) 与
    setup_notify_webhook (systemd EnvironmentFile URL 转义) 两处重复逻辑。

    转义规则:
      \\  →  \\\\  (反斜杠, 必须最先处理)
      "   →  \\"  (闭合引号)
    extra_chars 中的每个字符额外做 \\ 前缀转义 (如 '$' 用于 EnvironmentFile)。
    """
    # [PATCH-143 FIX-5] 断言: extra_chars 不含 \\ 和 \", 防止双重转义
    if chr(92) in extra_chars or chr(34) in extra_chars:
        raise ValueError("_escape_double_quoted: extra_chars must not contain backslash or double-quote, got: %r" % extra_chars)
    # [FIX-A8] 重复字符检测: 'aa' → 对 'a' 双重转义
    if len(set(extra_chars)) != len(extra_chars):
        raise ValueError(
            "_escape_double_quoted: extra_chars has duplicates: %r" % extra_chars)
    s = value.replace(chr(92), chr(92) * 2).replace(chr(34), chr(92) + chr(34))
    for ch in extra_chars:
        s = s.replace(ch, chr(92) + ch)
    return s


def _unescape_single_quoted(value: str) -> str:
    """反转义 PHP 单引号字面量中的转义序列 (wp-config 密码恢复)。

    [V3.2.117] 提取自 _recover_existing_db_pass 的内联 replace 链。

    规则 (顺序不可调换):
      \\\\  →  \\  (反斜杠, 必须最先处理)
      \\'  →  '
    """
    return value.replace(chr(92) + chr(92), chr(92)).replace(chr(92) + chr(39), chr(39))


# ---------------------------------------------------------------------------
# [PATCH-259] 统一安全入口点 — 消除分散实现的遗漏风险
# ---------------------------------------------------------------------------

# ── 1. 固定 Git 模块版本字典 (单一事实来源) ──────────────────────────
# 所有需要 git clone 的第三方 Nginx 模块在此统一登记。
# 更新流程: 审查新版本后修改此表中的 commit hash, 所有调用方自动生效。
# key: 模块名 (目录名)
# value: (git_url, pinned_tag, description)
# [PATCH-261c] 改用 git tag 替代 commit hash。
# GitHub 浅克隆不支持按 hash fetch (uploadpack.allowReachableSHA1InWant
# 默认关闭), 导致所有 pinned commit 全部不可达降级为 HEAD。
# git clone --depth=1 --branch <tag> 完美支持, 且 tag 可读性更好。
