# ── 2. 统一密码文件读取 (模块级, 可被实例方法和模块函数共用) ─────────
def _read_root_pwd_file(pwd_path: str) -> str:
    """安全读取 MariaDB root 密码文件, 含权限和字符集校验。

    [PATCH-259] 提取自 WPDeployManager._read_root_pwd_safe(),
    统一为模块级函数, 消除 _cleanup_ghost_sites 等模块级代码
    直接 read_text 绕过权限校验的风险。

    Returns: 密码字符串, 或 "" (文件不存在/权限异常/字符集非法)。
    """
    _p = Path(pwd_path)
    if not _p.exists():
        return ""
    try:
        _st = os.stat(str(_p))
        _mode = stat.S_IMODE(_st.st_mode)
        if _mode & 0o077:
            logging.warning(
                t("warn_pwd_file_perms",
                  path=_p, mode=_mode))
            return ""
        _content = _p.read_text(encoding="utf-8").strip()
        if _is_safe_password(_content):
            return _content
        if _content:
            logging.warning(
                t("warn_pwd_file_charset", path=_p))
        return ""
    except OSError as _e:
        logging.warning(t("warn_pwd_file_read_error", path=_p, err=_e))
        return ""


# ── 3. 统一 SQL 安全校验 (模块级, 可被 run_sql 和独立代码共用) ──────
def _validate_sql_safe(sql: str) -> str:
    """校验 SQL 语句安全性, 返回空字符串表示通过, 否则返回错误描述。

    [PATCH-259] 提取自 WPDeployManager.run_sql() 的前置校验逻辑,
    统一为模块级函数, 使 _cleanup_ghost_sites 等不经 run_sql() 管道
    的代码也能复用同一套安全检查。

    检查项:
      - 拒绝 NUL (\\x00), SUB (\\x1a), 及其他 C0 控制字符 (放行 \\t \\n \\r)
      - 校验所有反引号引用的标识符符合 [a-zA-Z0-9_]+ 白名单
    """
    for _ch in sql:
        _ord = ord(_ch)
        if _ord == 0x00 or _ord == 0x1a or (
            _ord < 0x20 and _ch not in ('\t', '\n', '\r')
        ):
            return "SQL contains dangerous control char %s" % hex(_ord)
    for _bt in re.finditer(r'`([^`]+)`', sql):
        _id = _bt.group(1)
        if not re.fullmatch(r'[a-zA-Z0-9_]+', _id):
            return "SQL contains unsafe backtick-quoted identifier: %r" % _id
    return ""  # 通过


# ── 4. _safe_rmtree — 符号链接安全的递归删除 ────────────────────────
def _safe_rmtree(path: str, *, ignore_errors: bool = False,
                 parent_guard: Optional[str]=None) -> bool:
    """[PATCH-260] 统一 shutil.rmtree 入口, 含符号链接防护。

    shutil.rmtree 跟随符号链接递归删除。攻击者可在目标路径预创建
    符号链接指向任意目录, 以 root 权限递归删除。

    检查项:
      1. 目标本身是否为符号链接 → 仅 unlink 链接, 不跟随
      2. 目标 resolve 后是否在 parent_guard 内 → 防止挂载穿越
      3. 通过后执行 shutil.rmtree

    Args:
        path:         待删除路径 (str 或 Path)
        ignore_errors: 透传给 shutil.rmtree
        parent_guard:  可选的父目录 (str 或 Path), 校验 resolve 后包含关系
    Returns:
        True 删除成功, False 跳过 (符号链接/包含校验失败)
    """
    _p = Path(path)
    if _p.is_symlink():
        logging.warning(
            t("warn_rmtree_symlink",
              path=_p, target=os.readlink(str(_p))))
        try:
            _p.unlink()
        except OSError:
            pass
        return False
    if parent_guard is not None:
        try:
            _resolved = _p.resolve()
            _guard = Path(parent_guard).resolve()
            _common = os.path.commonpath([str(_resolved), str(_guard)])
            if _common != str(_guard):
                logging.warning(
                    t("warn_rmtree_outside_guard",
                      path=_p, guard=parent_guard))
                return False
        except (ValueError, OSError):
            logging.warning(
                t("warn_rmtree_containment_error", path=_p))
            return False
    try:
        shutil.rmtree(str(_p), ignore_errors=ignore_errors)
        return True
    except OSError as _e:
        if not ignore_errors:
            logging.warning(t("warn_rmtree_failed", path=_p, err=_e))
        return False


# ── 5. _safe_copy2 — 符号链接安全的文件复制 ──────────────────────────
def _md5_noncrypto(data: bytes = b"") -> "hashlib._Hash":
    """[PATCH-283F] FIPS-safe MD5: 所有 md5 调用均为非安全用途 (DB 名截断哈希等)。

    RHEL/CentOS FIPS 模式下, _md5_noncrypto() 抛 ValueError。
    Python 3.9+ 支持 usedforsecurity=False 显式标记非密码学用途。
    """
    try:
        return hashlib.md5(data, usedforsecurity=False)
    except TypeError:
        return hashlib.md5(data)  # Python <3.9


def _sha1_noncrypto(data: bytes = b"") -> "hashlib._Hash":
    """[PATCH-283F] FIPS-safe SHA1: WP-CLI 下载校验等非安全用途。"""
    try:
        return hashlib.sha1(data, usedforsecurity=False)
    except TypeError:
        return hashlib.sha1(data)


def _safe_copy2(src: str, dst: str) -> bool:
    """[PATCH-260] 统一 shutil.copy2 入口, 对源和目标检查符号链接。

    shutil.copy2 跟随符号链接:
      - 源为符号链接 → 读取链接目标内容 (如 /etc/shadow 泄露到备份)
      - 目标为符号链接 → 写入链接目标位置 (如覆盖 /etc/crontab)

    [PATCH-261b FIX-B2] 增加目标路径符号链接检查。
    攻击者在备份目录预创建 nginx.conf → /etc/crontab 符号链接,
    copy2 跟随写入 → 以 root 权限覆盖任意文件。

    Returns:
        True 复制成功, False 跳过 (源或目标为符号链接)
    """
    _s = Path(src)
    if _s.is_symlink():
        logging.warning(
            t("warn_copy2_symlink_src",
              src=_s, target=os.readlink(str(_s))))
        return False
    # [FIX-B2] 目标路径符号链接检查
    _d = Path(dst)
    if _d.is_dir():
        # copy2("file.txt", "/dir/") → 实际写入 /dir/file.txt
        _actual_dst = _d / _s.name
    else:
        _actual_dst = _d
    if _actual_dst.is_symlink():
        logging.warning(
            t("warn_copy2_symlink_dst",
              dst=_actual_dst, target=os.readlink(str(_actual_dst))))
        return False
    try:
        shutil.copy2(str(src), str(dst))
        return True
    except OSError as _e:
        logging.warning(t("warn_copy2_failed", src=src, dst=dst, err=_e))
        return False


# ── 6. _safe_mkstemp — 创建瞬间即 fchmod 的临时文件 ──────────────────
def _safe_mkstemp(prefix: str = "", suffix: str = "",
                  dir_path: str = "", mode: int = 0o600) -> tuple:
    """[PATCH-260] 统一 tempfile.mkstemp 入口, 创建瞬间设置精确权限。

    标准 mkstemp 权限受 umask 影响 (如 umask 0o077 → 0o600,
    但 umask 0o022 → 0o644)。此函数在 mkstemp 返回后立即 fchmod,
    确保权限从创建瞬间生效, 不依赖 umask。

    Returns:
        (fd, path) 元组, 与 tempfile.mkstemp 相同
    """
    kwargs = {}
    if prefix:
        kwargs['prefix'] = prefix
    if suffix:
        kwargs['suffix'] = suffix
    if dir_path:
        kwargs['dir'] = dir_path
    fd, path = tempfile.mkstemp(**kwargs)
    try:
        os.fchmod(fd, mode)
    except OSError:
        # fchmod 失败: 检查实际权限是否可接受
        try:
            _actual = os.fstat(fd).st_mode & 0o777
            if _actual & 0o077:  # group/other 可访问
                os.close(fd)
                try:
                    os.unlink(path)
                except OSError:
                    pass
                raise OSError(
                    "_safe_mkstemp: fchmod failed and actual "
                    "permissions 0o%03o allow group/other access" % _actual)
        except OSError:
            # [PATCH-276 FIX-T2] fstat 也失败: 关闭 fd 防泄漏后 re-raise。
            # 原代码在此路径未关闭 fd, 导致文件描述符泄漏。
            try:
                os.close(fd)
            except OSError:
                pass
            try:
                os.unlink(path)
            except OSError:
                pass
            raise
    return fd, path


# ── 7. _verify_gzip_integrity — 统一 gzip -t 校验 ───────────────────
def _verify_gzip_integrity(gz_path: str, timeout: int = 120) -> bool:
    """[PATCH-260] 统一 gzip -t 完整性校验。

    4 处相同模式的单一事实来源: backup verify / lightweight backup /
    restore database / restore webroot。

    Returns:
        True 校验通过, False 失败
    """
    try:
        _r = subprocess.run(
            ["gzip", "-t", str(gz_path)],
            stdout=subprocess.PIPE, stderr=subprocess.PIPE,
            encoding='utf-8', errors='replace',
            timeout=timeout, check=False)
        if _r.returncode != 0:
            logging.warning(
                t("warn_gzip_check_failed",
                  path=gz_path, rc=_r.returncode,
                  stderr=(_r.stderr or "").strip()[:200]))
            return False
        return True
    except subprocess.TimeoutExpired:
        logging.warning(
            t("warn_gzip_check_timeout",
              path=gz_path, timeout=timeout))
        return False
    except Exception as _e:
        logging.warning(
            t("warn_gzip_check_error",
              path=gz_path, err=_e))
        return False


def _drain_pipe_with_select(fd_num: int, max_bytes: int=2 * 1024 * 1024,
                            timeout: int=30.0) -> bool:
    """Non-blocking pipe drain using select() with timeout.

    [PATCH-199] Replaces blocking pipe.read() in stderr drain threads.
    Eliminates fd reuse race (audit #10): select() detects EOF when
    child exits (kernel closes pipe write-end). No external fd close needed.

    Args:
        fd_num:    File descriptor number (int) to drain.
        max_bytes: Maximum bytes to read (OOM protection).
        timeout:   Total drain timeout in seconds.
    Returns:
        bytes read from the pipe.
    """
    import select as _sel199
    chunks = []
    total = 0
    remaining = timeout
    while remaining > 0:
        _t0 = time.monotonic()
        try:
            readable, _, _ = _sel199.select([fd_num], [], [],
                                            min(remaining, 1.0))
        except (ValueError, OSError):
            break  # fd closed or invalid
        if readable:
            try:
                chunk = os.read(fd_num, min(65536, max_bytes - total))
                if not chunk:
                    break  # EOF
                chunks.append(chunk)
                total += len(chunk)
                if total >= max_bytes:
                    break
            except OSError:
                break
        remaining -= (time.monotonic() - _t0)
    return b"".join(chunks)


def _env_lang() -> str:
    """Return language from environment variables only (ignores config file).

    [V3.2.135] P3-1 审计说明: 优先级 WP_LANG > LANG > LC_ALL > LANGUAGE
    与 POSIX 标准 (LANGUAGE > LC_ALL > LC_* > LANG) 不同。这是有意设计:
    - WP_LANG 是应用级覆盖, 最高优先级合理;
    - LANG 在大多数服务器上是唯一设置的语言变量 (LC_ALL 通常未设置),
      将 LANG 置于 LC_ALL 之前可在最常见场景下更快命中;
    - 此函数仅用于 zh/en 二选一的粗粒度判断, 不影响 locale 精确匹配。
    若需严格 POSIX 优先级, 请使用 locale.getdefaultlocale()。
    """
    raw = (
        os.environ.get("WP_LANG", "")
        or os.environ.get("LANG", "")
        or os.environ.get("LC_ALL", "")
        or os.environ.get("LANGUAGE", "")
    ).lower()
    return "zh" if raw.startswith("zh") else "en"


def _read_lang_config() -> Optional[tuple]:  # (chosen, env_at_choice) | None
    """Parse the language config file.

    Returns:
        (chosen, env_at_choice)  — both are 'zh' or 'en'
        (chosen, None)           — old single-token format; env unknown
        None                     — file absent or unreadable
    """
    try:
        if _LANG_CONFIG_FILE.exists():
            val = _LANG_CONFIG_FILE.read_text(encoding="utf-8").strip().lower()
            if ":" in val:
                parts = val.split(":", 1)
                if parts[0] in ("zh", "en") and parts[1] in ("zh", "en"):
                    return (parts[0], parts[1])
            elif val in ("zh", "en"):
                return (val, None)
    except OSError:
        pass
    return None


def _saved_lang() -> Optional[str]:  # saved chosen language or None
    """Compatibility shim: return saved chosen language or None."""
    cfg = _read_lang_config()
    return cfg[0] if cfg is not None else None



# [V3.2.12] P2-9: 添加线程锁保护缓存变量，防止未来多线程调用时数据竞争
import threading as _threading
# [V3.2.102] P3-2: GIL 依赖说明 —
# 无锁快速路径 (if _CHINA_CLOUD_CACHE is not None: return) 依赖 CPython GIL
# 保证单字节码指令间的原子读取。Python 3.13+ 实验性 --disable-gil (PEP 703)
# 可能打破此假设; 届时需将快速路径改为 lock.acquire() 或使用 threading.Event。
# 当前脚本仅支持 CPython, 此注释为前瞻性文档。
# [V3.2.136] AUDIT C-2: 运行时 GIL 状态检查
try:
    if hasattr(sys, '_is_gil_enabled') and not sys._is_gil_enabled():
        logging.warning("[AUDIT C-2] Running with GIL disabled (PEP 703). "
                        "Double-checked locking in _is_china_cloud / "
                        "_detect_nginx_http2_directive may be unsafe. "
                        "Falling back to always-lock mode.")
        _NO_GIL_MODE = True
    else:
        _NO_GIL_MODE = False
except Exception:
    _NO_GIL_MODE = False
_CHINA_CLOUD_CACHE: Optional[str] = None  # [V3.2.3] M-9: Python 3.6 compat
_CHINA_CLOUD_LOCK = _threading.Lock()


def _set_china_cloud_cache(value: str) -> str:
    """[V3.2.13] P1-1: Thread-safe cache write for _is_china_cloud().
    [V3.2.22] P1-2: 双重检查锁 — 调用方已在 _CHINA_CLOUD_LOCK 内。
    [PATCH FIX-5] 去掉与锁语义矛盾的 "if not None: return" 二次检查：
    调用方持有锁时此函数是唯一写者，条件永远不会触发，
    保留反而暗示存在无锁调用路径，造成误导。
    """
    global _CHINA_CLOUD_CACHE
    # [PATCH FIX-5] 直接写入，调用方保证在锁内调用，无需二次检查
    _CHINA_CLOUD_CACHE = value
    return value

def _is_china_cloud() -> str:
    """检测是否运行在国内云服务器上。返回云厂商名称或空字符串。

    [V3.1.4] F3: 结果缓存至模块级变量, 避免重复 HTTP 请求。
    [V3.3.0] 新增: 天翼云/京东云/火山引擎/UCloud/百度云/金山云检测。
    [V3.2.90] B-1: 整个函数体在 _CHINA_CLOUD_LOCK 内执行,
    防止多线程场景下所有层探测被重复触发。

    检测策略（每层均短路返回）:
      1. /etc/os-release 关键词匹配 — 速度最快, 覆盖定制发行版
      2. 各厂商专用 release 文件    — /etc/ctyun-release 等
      3. DMI sysfs 硬件信息         — product_name / sys_vendor
      4. 厂商专有元数据端点          — HTTP 超时 1s, 失败静默
      5. 通用 IMDS 端点              — 169.254.169.254 + 厂商特征响应
    """
    # [V3.2.90] B-1: 双重检查锁 — 快速路径无锁读, 慢速路径加锁保护全部探测层
    # [AUDIT I-2] GIL 禁用时跳过无锁快速路径, 直接加锁
    if not _NO_GIL_MODE and _CHINA_CLOUD_CACHE is not None:
        return _CHINA_CLOUD_CACHE
    with _CHINA_CLOUD_LOCK:
        # 二次检查: 另一线程可能在我们等待锁期间已完成探测
        if _CHINA_CLOUD_CACHE is not None:
            return _CHINA_CLOUD_CACHE
        return _is_china_cloud_locked()


def _is_china_cloud_locked() -> str:
    """_is_china_cloud() 的实际探测逻辑, 由调用方保证在锁内执行。

    [AUDIT RACE-01] 安全契约:
      此函数操作模块级全局状态 _CHINA_CLOUD_CACHE, 必须在
      _CHINA_CLOUD_LOCK 持有期间调用。在锁外调用将导致:
      - CPython (GIL): 功能正确但违反设计意图
      - 非 CPython / PEP 703 no-GIL: 数据竞争, 未定义行为
      函数名以 _locked 结尾作为调用约束提示。
    """
    _cloud_probe_t0 = time.monotonic()  # [PATCH-144 L-6] 总探测耗时上限
    # [AUDIT L-1] 允许通过环境变量跳过云检测 (容器环境/安全审计)
    # [AUDIT PERF-02] 性能说明: 层4 HTTP 元数据探测在非云环境下
    # 串行等待 4×1s=4s。对于频繁调用的场景 (如 self-update 虽已有
    # 提前返回), 建议:
    #   1. 设置 WP_SKIP_CLOUD_DETECT=1 跳过 (已支持)
    #   2. 首次检测结果已缓存至 _CHINA_CLOUD_CACHE 模块变量,
    #      同一进程内后续调用走无锁快速路径, 不重复探测
    # 未来优化方向: 将检测结果持久化到磁盘文件 (类似 _LANG_CONFIG_FILE),
    # 跨进程复用, 消除每次脚本启动的固定探测开销。
    if os.environ.get("WP_SKIP_CLOUD_DETECT", "").strip() == "1":
        return _set_china_cloud_cache("")

    # ── 层 1: /etc/os-release ──────────────────────────────────────────────
    try:
        osr = Path("/etc/os-release").read_text(encoding="utf-8").lower()
        if any(k in osr for k in ("alibaba", "alinux", "anolis", "aliyun")):
            return _set_china_cloud_cache("Alibaba Cloud")
        if any(k in osr for k in ("tencentos", "tlinux", "tencent")):
            return _set_china_cloud_cache("Tencent Cloud")
        if any(k in osr for k in ("huaweicloud", "euler", "huawei")):
            return _set_china_cloud_cache("Huawei Cloud")
        if any(k in osr for k in ("ctyun", "chinatelecom", "ct-cloud")):
            return _set_china_cloud_cache("CTYun")
        if any(k in osr for k in ("jdcloud", "jd cloud", "jdos")):
            return _set_china_cloud_cache("JD Cloud")
        if any(k in osr for k in ("volcengine", "velinux", "bytedance")):
            return _set_china_cloud_cache("Volcano Engine")
        if "ucloud" in osr:
            return _set_china_cloud_cache("UCloud")
        if any(k in osr for k in ("bce", "baiduyun", "baidu cloud")):
            return _set_china_cloud_cache("Baidu Cloud")
        if any(k in osr for k in ("ksyun", "kingsoft")):
            return _set_china_cloud_cache("Kingsoft Cloud")
    except OSError:
        pass

    # ── 层 2: 厂商专用 release 文件 ───────────────────────────────────────
    _release_files = [
        ("/etc/ctyun-release",       "CTYun"),
        ("/etc/ct-release",          "CTYun"),
        ("/etc/jdcloud-release",     "JD Cloud"),
        ("/etc/ve-release",          "Volcano Engine"),
        ("/etc/volcengine-release",  "Volcano Engine"),
        ("/etc/ucloud-release",      "UCloud"),
        ("/etc/bce-release",         "Baidu Cloud"),
        ("/etc/baidu-release",       "Baidu Cloud"),
        ("/etc/ksyun-release",       "Kingsoft Cloud"),
    ]
    for _rf, _vendor in _release_files:
        if Path(_rf).exists():
            return _set_china_cloud_cache(_vendor)

    # ── 层 3: DMI sysfs 硬件信息 ──────────────────────────────────────────
    for dmi_path in ("/sys/class/dmi/id/product_name",
                     "/sys/class/dmi/id/sys_vendor",
                     "/sys/class/dmi/id/board_vendor"):
        try:
            dmi = Path(dmi_path).read_text(encoding="utf-8").lower().strip()
            if "alibaba" in dmi or "aliyun" in dmi:
                return _set_china_cloud_cache("Alibaba Cloud")
            if "tencent" in dmi:
                return _set_china_cloud_cache("Tencent Cloud")
            if "huawei" in dmi:
                return _set_china_cloud_cache("Huawei Cloud")
            if "ctyun" in dmi or "chinatelecom" in dmi:
                return _set_china_cloud_cache("CTYun")
            if "jdcloud" in dmi or "jd cloud" in dmi:
                return _set_china_cloud_cache("JD Cloud")
            if "volcengine" in dmi or "bytedance" in dmi:
                return _set_china_cloud_cache("Volcano Engine")
            if "ucloud" in dmi:
                return _set_china_cloud_cache("UCloud")
            if "baiduyun" in dmi or "baidu cloud" in dmi or "baidu-cloud" in dmi:  # [PATCH-L1] 收紧匹配
                return _set_china_cloud_cache("Baidu Cloud")
            if "ksyun" in dmi or "kingsoft" in dmi:
                return _set_china_cloud_cache("Kingsoft Cloud")
        except OSError:
            pass

    # ── 层 4: 厂商专有元数据端点 ───────────────────────────────────────────
    # [PATCH-144 L-6] 文件/DMI 探测已耗时过长时跳过 HTTP 层
    if time.monotonic() - _cloud_probe_t0 > 8:
        return _set_china_cloud_cache("")
    import urllib.request as _ureq
    _meta_probes = [
        # 阿里云 ECS 专有地址 (link-local, 仅限 ECS 实例内部)
        ("http://100.100.100.200/latest/meta-data/region-id",
         {"Metadata": "true"}, "Alibaba Cloud"),
        # 腾讯云 CVM 专有地址
        ("http://169.254.0.23/meta-data/instance-id",
         {"Metadata": "true"}, "Tencent Cloud"),
        # 京东云专有地址
        ("http://100.80.80.80/latest/meta-data/instance-id",
         {"Metadata": "true"}, "JD Cloud"),
        # 火山引擎专有地址
        ("http://100.96.0.96/latest/meta-data/",
         {}, "Volcano Engine"),
    ]
    for _url, _headers, _vendor in _meta_probes:
        try:
            _req = _ureq.Request(_url, headers=_headers)
            with _ureq.urlopen(_req, timeout=1) as _resp:
                if _resp.read():
                    return _set_china_cloud_cache(_vendor)
        except Exception as _exc_1178:
            logging.debug("[PATCH-276] L1178: %s", _exc_1178)

    # [PATCH-144 L-6] 总探测耗时超限时短路返回 (层 5 网关)
    if time.monotonic() - _cloud_probe_t0 > 10:
        return _set_china_cloud_cache("")
    # ── 层 5: 通用 IMDS 端点 (169.254.169.254) [PATCH-144 L-6 guarded] ──
    # [V3.2.11] P0-3: 改用具体端点而非扫描整个 user-data；
    # 仅匹配不可能在 AWS/GCP instance-id 中出现的厂商特有前缀，
    # 防止 EC2 用户自定义 user-data 触发误判。
    _imds_probes = [
        # [V3.2.12] P0-2: 华为云 OpenStack meta_data.json 返回 JSON，
        # 其 availability_zone 字段值以 "cn-" 开头 (如 "cn-north-4a")，
        # 而 AWS/GCP 的 IMDS 不使用该端点格式，不会误判。
        ("http://169.254.169.254/openstack/latest/meta_data.json",
         {"Metadata": "true"}, "cn-", "Huawei Cloud"),
        # UCloud 实例 ID 以 "uhost-" 开头
        ("http://169.254.169.254/latest/meta-data/instance-id",
         {"Metadata": "true"}, "uhost-", "UCloud"),
        # 百度云实例 ID 以 "i-" 开头但 region 固定含 "bj/bd/gz/su"
        ("http://169.254.169.254/latest/meta-data/local-hostname",
         {"Metadata": "true"}, "bce-", "Baidu Cloud"),
    ]
    for _imds_url, _imds_hdr, _imds_prefix, _imds_vendor in _imds_probes:
        try:
            _req = _ureq.Request(_imds_url, headers=_imds_hdr)
            with _ureq.urlopen(_req, timeout=1) as _resp:
                _body = _resp.read(512).decode("utf-8", errors="replace")
                # [V3.2.13] P0-1: Huawei Cloud meta_data.json returns JSON;
                # parse availability_zone instead of raw prefix matching.
                if _imds_vendor == "Huawei Cloud":
                    try:
                        _meta = json.loads(_body)
                        _az = str(_meta.get("availability_zone", "")).lower()
                        if _az.startswith(_imds_prefix):
                            return _set_china_cloud_cache(_imds_vendor)
                    except (ValueError, KeyError, TypeError):
                        pass
                    continue
                _body_lower = _body.strip().lower()
                # [V3.2.102] P3-4: 改用 splitlines 逐行匹配, 兼容单行 / 多行响应。
                # 原 "\n" + prefix 模式在单行响应时永远不匹配。
                if any(_ln.strip().startswith(_imds_prefix)
                       for _ln in _body_lower.splitlines() if _ln.strip()):
                    return _set_china_cloud_cache(_imds_vendor)
        except Exception as _exc_1223:
            logging.debug("[PATCH-276] L1223: %s", _exc_1223)

    return _set_china_cloud_cache("")


# ---------------------------------------------------------------------------
# [PATCH-215] 国内网络环境检测 (区分国内云身份 vs 国内网络出口)
# ---------------------------------------------------------------------------
_CHINA_NETWORK_CACHE: Optional[bool] = None
_CHINA_NETWORK_LOCK = _threading.Lock()


def _is_china_network() -> bool:
    """检测当前服务器的网络出口是否在中国大陆。

    与 _is_china_cloud() 的区别:
      _is_china_cloud()   → 云厂商身份 (阿里云香港也返回 "Alibaba Cloud")
      _is_china_network() → 网络出口位置 (阿里云香港返回 False)

    用于决定: 下载源优先级 (国内镜像 ghfast/cn.wordpress.org vs 海外直连)

    检测策略 (每层短路返回):
      1. 非国内云 → False
      2. 国内云 → region metadata → cn- 前缀 → True
      3. Region 不可用 → GitHub HEAD 连通性 → <2s 响应 → False
      4. 默认 → True (保守: 国内云 + 未知 region + GitHub 不通)

    结果缓存至模块级变量, 同一进程内仅探测一次。
    """
    global _CHINA_NETWORK_CACHE
    # [PATCH-252 FIX-5] 与 _is_china_cloud() L590 对齐:
    # GIL 禁用时跳过无锁快速路径, 直接加锁, 防止数据竞争。
    if not _NO_GIL_MODE and _CHINA_NETWORK_CACHE is not None:
        return _CHINA_NETWORK_CACHE
    with _CHINA_NETWORK_LOCK:
        if _CHINA_NETWORK_CACHE is not None:
            return _CHINA_NETWORK_CACHE
        _result = _detect_china_network_locked()
        _CHINA_NETWORK_CACHE = _result
        return _result


def _detect_china_network_locked() -> bool:
    """_is_china_network() 的实际检测逻辑, 由调用方保证在锁内执行"""
    import urllib.request as _ur_cn

    cloud = _is_china_cloud()
    if not cloud:
        return False

    # 环境变量覆盖 (测试/调试用)
    _env_cn = os.environ.get("WP_CHINA_NETWORK", "").strip().lower()
    if _env_cn == "0" or _env_cn == "false":
        logging.info(t("info_china_net_forced", mode="overseas", val="0"))
        return False
    if _env_cn == "1" or _env_cn == "true":
        logging.info(t("info_china_net_forced", mode="china", val="1"))
        return True

    # ── 层 1: 云厂商 Region Metadata ──────────────────────────
    # 所有国内云的中国大陆区域 ID 均以 "cn-" 开头 (跨厂商一致)
    # 海外区域: ap-southeast-1 / us-west-1 / eu-central-1 等
    _region_probes = [
        # (url, headers, cloud_keyword)
        ("http://100.100.100.200/latest/meta-data/region-id",
         {"Metadata": "true"}, "Alibaba"),
        ("http://169.254.0.23/meta-data/placement/zone",
         {"Metadata": "true"}, "Tencent"),
        ("http://100.80.80.80/latest/meta-data/placement/availability-zone",
         {"Metadata": "true"}, "JD"),
        ("http://100.96.0.96/latest/meta-data/placement/availability-zone",
         {}, "Volcano"),
    ]
    for _url, _headers, _vendor_kw in _region_probes:
        if _vendor_kw not in cloud:
            continue
        try:
            _req = _ur_cn.Request(_url, headers=_headers)
            with _ur_cn.urlopen(_req, timeout=2) as _resp:
                _region = _resp.read(256).decode("utf-8", errors="replace").strip().lower()
                if _region:
                    _is_cn = _region.startswith("cn-")
                    logging.info(t("info_patch_215_region_china_network"),
                        cloud, _region, _is_cn)
                    return _is_cn
        except Exception as _exc_1309:
            logging.debug("[PATCH-276] timeout: %s", _exc_1309)

    # 华为云: JSON metadata, availability_zone 字段
    if "Huawei" in cloud:
        try:
            _req = _ur_cn.Request(
                "http://169.254.169.254/openstack/latest/meta_data.json",
                headers={"Metadata": "true"})
            with _ur_cn.urlopen(_req, timeout=2) as _resp:
                _body = _resp.read(512).decode("utf-8", errors="replace")
                _meta = json.loads(_body)
                _az = str(_meta.get("availability_zone", "")).lower()
                if _az:
                    _is_cn = _az.startswith("cn-")
                    logging.info(t("info_patch_215_huawei_cloud_az_china_network"),
                        _az, _is_cn)
                    return _is_cn
        except Exception as _exc_1327:
            logging.debug("[PATCH-276] timeout: %s", _exc_1327)

    # UCloud / 百度云 / 金山云: 无标准 region endpoint, 走层 2

    # ── 层 2: GitHub 连通性测试 ───────────────────────────────
    # 中国大陆: github.com 通常 >3s 或不可达
    # 海外 (含港澳台): <2s 响应
    try:
        _req = _ur_cn.Request(
            "https://github.com",
            method="HEAD",
            headers={"User-Agent": "wp-ssl-bootstrap"})
        _t0 = time.monotonic()
        with _ur_cn.urlopen(_req, timeout=3) as _resp:
            _elapsed = time.monotonic() - _t0
            if _elapsed < 2.0:
                logging.info(t("info_patch_215_github_head_responded_in_overseas"), _elapsed, cloud)
                return False
    except Exception as _exc_1346:
        logging.debug("[PATCH-276] timeout: %s", _exc_1346)

    # ── 层 3: 默认 (保守) ─────────────────────────────────────
    logging.info(t("info_patch_215_region_unknown_github_unreachable_a"), cloud)
    return True





def _prompt_china_cloud_lang() -> None:
    """国内云首次运行时提示选择中文"""
    global _LANG
    if _read_lang_config() is not None:
        return
    if os.environ.get("WP_LANG", "").strip():
        return
    if not sys.stdin.isatty():
        return
    # [V3.2.3] L-4: self-update 无需云检测 HTTP 请求
    if len(sys.argv) > 1 and sys.argv[1] == "self-update":
        return
    cloud = _is_china_cloud()
    if not cloud:
        return
    print(t("prompt_china_cloud_detected", cloud=cloud))
    try:
        choice = input("选择 / Choose [1/2, Enter=中文]: ").strip()
    except (EOFError, KeyboardInterrupt):
        print()
        return
    if choice in ("", "1"):
        _LANG = "zh"
    elif choice == "2":
        _LANG = "en"
    else:
        _LANG = "zh"
    _write_lang_file(_LANG, _env_lang())
    print(f"语言已设置 / Language set → {_LANG.upper()}")


def _detect_lang() -> str:
    """Detect display language.

    Priority (highest first):
      1. /root/.wp_ssl_lang  (written by --lang on first use)
      2. WP_LANG / LANG / LC_ALL / LANGUAGE env vars
      3. Default: 'en'

    [V3.2.90] B-9 审计: 当 saved 为 "zh" 且环境变量指向其他语言时,
    saved 优先级高于 env (符合设计意图); 函数逻辑完整, 无 bug。
    """
    saved = _saved_lang()
    return saved if saved is not None else _env_lang()


def _prompt_lang_change() -> None:
    """仅当系统语言相对上次选择时发生了真实切换时才询问用户。

    旧格式兼容 (env_at_choice 为 None): 静默迁移, 本次不弹提示。
    """
    global _LANG

    cfg = _read_lang_config()
    if cfg is None:
        return

    chosen, env_at_choice = cfg

    if _LANG != chosen:
        return

    if os.environ.get("WP_LANG_NOCHECK", "").strip() == "1":
        return

    if not sys.stdin.isatty():
        return

    current_env = _env_lang()

    # 旧格式迁移
    if env_at_choice is None:
        _write_lang_file(chosen, current_env)
        return

    # 系统语言未变 — 不打扰
    if current_env == env_at_choice:
        return

    # 系统语言变了 → 询问
    print(
        f"\n[语言变更提示] 系统语言已从 {env_at_choice.upper()} 切换至 "
        f"{current_env.upper()}，当前保存语言: {chosen.upper()}"
    )
    print(
        f"    [Language change] System language changed: "
        f"{env_at_choice.upper()} → {current_env.upper()}, "
        f"saved preference: {chosen.upper()}"
    )
    print(f"  [1] 保留 {chosen.upper()} / Keep {chosen.upper()} (Enter)")
    print(f"  [2] 跟随系统 → {current_env.upper()} / Follow system → {current_env.upper()}")
    print( "  [3] 其他 / Other (进入手动输入 / Enter manually)")  # [AUDIT F-1]
    print()

    try:
        choice = input("选择 / Choose [1/2/3 or zh/en, Enter=keep]: ").strip().lower()
    except (EOFError, KeyboardInterrupt):
        print()
        return

    if choice in ("", "1"):
        _write_lang_file(chosen, current_env)
        return

    if choice == "2":
        new_chosen = current_env
    elif choice in ("zh", "en"):
        new_chosen = choice
    else:
        try:
            code = input("语言代码 / Language code (zh/en): ").strip().lower()
        except (EOFError, KeyboardInterrupt):
            print()
            return
        if code not in ("zh", "en"):
            print(f"无效代码 / Invalid: \'{code or '(empty)'}\', keeping {chosen.upper()}")
            _write_lang_file(chosen, current_env)
            return
        new_chosen = code

    _LANG = new_chosen
    _write_lang_file(new_chosen, current_env)
    print(f"语言已切换 / Language switched → {new_chosen.upper()}")


_LANG: str = _detect_lang()  # noqa: M-9 compat ok  # thread-safety: main-thread only

