logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
    datefmt="%Y-%m-%d %H:%M:%S",
    stream=sys.stderr,  # [V2.9.5] 日志输出到 stderr，避免与 stdout 数据流混杂
)


# ---------------------------------------------------------------------------
# 命令执行结果（借鉴 sooth_monitor 错误分类体系）
# ---------------------------------------------------------------------------
class CmdResult:
    """命令执行结果，携带错误分类信息和命令输出。

    通过 __bool__ 返回 self.ok，保持与原 bool 返回值的向后兼容：
        if self.run_cmd([...]):   # 仍然有效
    需要详细信息时：
        result = self.run_cmd([...])
        if result.code == CmdResult.TIMEOUT: ...
        print(result.stdout)   # 命令标准输出
    """
    # 错误分类常量
    SUCCESS    = 0   # 命令成功
    RETRYABLE  = 1   # 暂时性错误，可重试
    TIMEOUT    = 2   # 执行超时
    PERMISSION = 3   # 权限不足
    FATAL      = 4   # 不可恢复的致命错误

    def __init__(self, ok: bool, code: int = 0, stdout: str = "", stderr: str = "") -> None:
        self.ok = ok
        self.code = code if not ok else self.SUCCESS
        self.stdout = stdout
        self.stderr = stderr

    def __bool__(self) -> bool:
        return self.ok

    def __repr__(self) -> str:
        labels = {0: "SUCCESS", 1: "RETRYABLE", 2: "TIMEOUT", 3: "PERMISSION", 4: "FATAL"}
        return f"CmdResult(ok={self.ok}, code={labels.get(self.code, self.code)})"

    @staticmethod
    def success(stdout: str = "") -> "CmdResult":
        return CmdResult(ok=True, code=CmdResult.SUCCESS, stdout=stdout)

    @staticmethod
    def classify_stderr(stderr: str, exit_code: int = -1) -> int:
        """根据 stderr 内容推断错误类别。

        [AUDIT L-4] exit_code 参数 (可选): 优先按退出码分类,
        stderr 关键词作为辅助。调用方可选传入 process.returncode。
        非英文系统 locale 下 stderr 关键词可能不匹配, exit_code
        提供更可靠的分类信号。-1 表示未提供 (向后兼容)。

        [V3.2.112] DEBT-2: 本方法用于通用命令 (systemctl/nginx/tar 等),
        不适用于 certbot 输出。certbot 有专用分类函数 classify_certbot_error(),
        两者对 "unauthorized" 等关键词的分类截然不同:
        - 本方法: unauthorized + 本地路径 → PERMISSION (文件系统授权)
        - certbot 专用: unauthorized → RETRYABLE (ACME challenge 验证失败, 换 CA 可能成功)
        在 certbot 上下文中误用本方法会导致本应重试的 CA 错误被标记为权限问题。
        """
        # [PATCH-140 FIX-L4] 优先按退出码分类 (非英文 locale 下 stderr
        # 关键词可能不匹配, 退出码更可靠)。-1 表示未提供, 跳过此层。
        if exit_code != -1:
            if exit_code == 126:
                return CmdResult.PERMISSION
            if exit_code == 127:
                return CmdResult.FATAL       # command not found
            if exit_code == 124:
                return CmdResult.TIMEOUT     # coreutils timeout(1) 退出码
            # 128+N = 被信号 N 终止 (如 137=SIGKILL 常见于 OOM)
            if exit_code > 128:
                # [PATCH-144 L-1] SIGINT(130)/SIGTERM(143) 是正常中断,
                # 不应归为 FATAL (会跳过重试逻辑和触发不必要告警)
                _sig_l1 = exit_code - 128
                # [AUDIT ERR-02] SIGKILL(9) 通常由 OOM Killer 触发,
                # 属于暂时性资源压力, 应归为 RETRYABLE 而非 FATAL,
                # 否则 OOM 掉的 certbot/mysqldump 会跳过 CA 容灾重试
                if _sig_l1 in (2, 9, 15):  # SIGINT, SIGKILL(OOM), SIGTERM
                    return CmdResult.RETRYABLE
                return CmdResult.FATAL
        err = stderr.lower()
        # 权限类
        # [V3.2.108] AUDIT-9: "unauthorized" 在本地路径上下文中属于 PERMISSION,
        # 在 ACME challenge 上下文中属于 RETRYABLE (下方单独处理)
        if any(k in err for k in (
            "permission denied", "access denied", "operation not permitted",
            "authentication required",
        )):
            return CmdResult.PERMISSION
        # 本地路径 + unauthorized 组合 → PERMISSION
        if "unauthorized" in err and any(p in err for p in (
            "/etc/letsencrypt", "/var/lib", "/run/", "/tmp/",
        )):
            return CmdResult.PERMISSION
        # 致命类（不可重试）
        if any(k in err for k in (
            "no space left on device", "read-only file system",
            "command not found", "no such file or directory",
            "syntax error", "invalid option",
        )):
            return CmdResult.FATAL
        # 超时类
        # [V3.2.136] AUDIT E-4: 全词边界匹配, 防止 "connect-timeout" 等误触发
        if re.search(r'\btimeout\b|\btimed out\b', err):
            return CmdResult.TIMEOUT
        # 默认为可重试
        return CmdResult.RETRYABLE


# ---------------------------------------------------------------------------
# 站点配置数据类
# ---------------------------------------------------------------------------
class SiteConfig:
    # 磁盘空间阈值 (MB)
    MIN_DISK_FREE_MB_DOWNLOAD = 500   # WordPress 下载+解压最低要求
    MIN_DISK_FREE_MB_EXTRACT  = 200   # 解压前二次检查
    MIN_DISK_FREE_MB_BACKUP   = 200   # [PATCH-146 P3-3] 备份前最低
    MIN_DISK_FREE_MB_CERT     = 20    # [PATCH-146 P3-3] SSL签发前最低
    DISK_OK_THRESHOLD_MB      = 500   # [PATCH-146 P3-3] status OK
    DISK_WARN_THRESHOLD_MB    = 200   # [PATCH-146 P3-3] status WARN

    def __init__(self, args: argparse.Namespace) -> None:
        self.domain = args.domain.lower().strip()
        # [V3.2.64] BUG-A: 用户输入 www.example.com 时自动剥离 www. 前缀，
        # 后续 _build_domain_args / _nginx_server_names 会自动添加 www 变体，
        # 确保 SSL 证书与 Nginx 同时覆盖 裸域名 + www 域名。
        if self.domain.startswith("www.") and self.domain.count(".") >= 2:
            _original = self.domain
            self.domain = self.domain[4:]  # strip "www."
            # [V3.2.66] BUG-D-1: 根据 _should_add_www() 输出准确的日志消息
            if _should_add_www(self.domain):
                logging.info(t("info_domain_normalized", orig=_original, norm=self.domain, reason=t("inline_www_auto_alias")))
            else:
                logging.info(t("info_domain_normalized", orig=_original, norm=self.domain, reason=t("inline_subdomain")))
        # [AUDIT M-6] 每标签最大 63 字符 (RFC 1035)
        if not re.match(r'^([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,}$', self.domain):
            print(t("err_domain_fmt", domain=self.domain))
            sys.exit(1)
        # [V2.9.5] DNS 规范最大 253 字符，防止超长域名触发下游缓冲区异常
        if len(self.domain) > 253:
            print(t("err_domain_len", n=len(self.domain)))
            sys.exit(1)

        # email 仅 deploy 子命令必填，renew / uninstall 可省略
        raw_email = getattr(args, 'email', None) or ''
        self.email = raw_email.lower().strip()
        # [V3.2.98] FIX-C1 (§3.4): self.email 已 .lower(), 移除冗余 A-Z
        # [AUDIT M-7] 增强 email 校验: 拒绝连续点号/点号开头结尾/超长地址
        if self.email and (
            len(self.email) > 254
            or not re.match(r'^[a-z0-9._%+\-]+@[a-z0-9]([a-z0-9.-]*[a-z0-9])?\.[a-z]{2,}$', self.email)
            or '..' in self.email
        ):  # [PATCH-BUG2] 加固：排除空格/控制字符
            print(t("err_email_fmt", email=self.email))
            sys.exit(1)

        # [V3.2.121] FIX-4: 委托共享编码函数, 与 _nginx_safe_name 保持同步
        sanitized_id = _encode_domain_id(self.domain)

        # [V3.2.5] A-10: 超长域名截断后追加短哈希, 避免碰撞
        # [AUDIT BUG-06] _encode_domain_id 对数字开头域名已加 wp_ 前缀,
        # 此处不可再加, 否则产生 wp_wp_ 双前缀 (如 123.example.com)
        _raw_db_name = sanitized_id if sanitized_id.startswith("wp_") else "wp_" + sanitized_id
        if len(_raw_db_name) > 64:
            _db_hash = _md5_noncrypto(sanitized_id.encode()).hexdigest()[:7]
            self.db_name = _raw_db_name[:56] + "_" + _db_hash
        else:
            self.db_name = _raw_db_name
        _raw_db_user = "u_" + sanitized_id
        if len(_raw_db_user) > 32:
            # [PATCH-H1] 超长时追加 5 位哈希防碰撞，与 db_name 处理方式一致
            _u_hash = _md5_noncrypto(sanitized_id.encode()).hexdigest()[:5]
            self.db_user = _raw_db_user[:26] + "_" + _u_hash
        else:
            self.db_user = _raw_db_user

        # 严格白名单字符集（纯字母数字），保证不可能注入 SQL 或 .cnf 转义问题
        self.db_pass = _generate_secure_password()  # [PATCH-146 P0-3]

        self.webroot_path = Path(f"{self._detect_webroot_base()}/{self.domain}")
        self.nginx_conf = Path(f"/etc/nginx/conf.d/{self.domain}.conf")

        run_dir = Path("/run")
        if not run_dir.exists():
            run_dir.mkdir(parents=True, exist_ok=True)
        self.lock_file = run_dir / f"{sanitized_id}_ssl_manager.lock"

        # [P4] systemd unit 文件名限制: 截断至 48 字符 + hash, 与 _nginx_safe_name 对齐
        if len(sanitized_id) > 48:
            _sd_hash = _md5_noncrypto(sanitized_id.encode()).hexdigest()[:7]
            self.systemd_prefix = sanitized_id[:40] + "_" + _sd_hash
        else:
            self.systemd_prefix = sanitized_id
        self.service_file = Path(f"/etc/systemd/system/{self.systemd_prefix}-ssl.service")
        self.timer_file = Path(f"/etc/systemd/system/{self.systemd_prefix}-ssl.timer")
        self.script_path = Path(os.path.abspath(__file__))

        self.dry_run = args.dry_run
        self.staging = args.staging
        # [V3.2.110] FIX-1: track explicit --staging / --no-staging
        self._staging_user_specified = (
            args.staging or getattr(args, 'no_staging', False)
        )
        self.cache_mode = getattr(args, 'cache', 'none') or 'none'
        # [PATCH-201 A] 追踪用户是否显式指定了 --cache, 防止自动探测覆盖用户意图。
        # 需同时匹配空格形式 (--cache none) 和等号形式 (--cache=none)。
        # 交互模式下 sys.argv 不含子命令参数, 但交互式 enable-ssl 会自行
        # 从站点配置注入 --cache, 不经过此处的自动探测路径, 因此 False 安全。
        self._cache_user_specified = any(
            a == '--cache' or a.startswith('--cache=')
            for a in sys.argv[1:]
        )
        # [PATCH-170 FIX-3] srcache 模块探测延迟到 WPDeployManager 阶段,
        # 允许先尝试自动编译, 编译失败才降级 FastCGI。
        # _ensure_srcache_modules() 在 Nginx 配置生成前调用。
        self.redis_cache = getattr(args, 'redis', False)  # [V2.9.8] Redis 对象缓存
        self.skip_deps = getattr(args, 'skip_deps', False)  # [V3.0.0] 跳过依赖安装
        self.allow_xmlrpc = getattr(args, 'allow_xmlrpc', False)  # [V3.0.3] 可选放开 XML-RPC
        self.php_version = getattr(args, 'php_version', None) or None
        self.wp_auto_install = getattr(args, 'wp_auto_install', False)  # [V3.0.16] P7
        self.optimize = getattr(args, 'optimize', False)  # [V3.0.16] P9
        self.http3 = getattr(args, 'http3', False)  # [PATCH-167 FIX-5]
        self.cloudflare = getattr(args, 'cloudflare', False)  # [V3.0.16] P12
        self.serve_dist = getattr(args, 'serve_dist', False)  # [PATCH-271]
        self.accept_redis_license = getattr(args, 'accept_redis_license', False)  # [PATCH-272]
        # [AUDIT-FIX BUG-3] 追踪安全相关布尔选项是否由用户显式指定,
        # 防止 _detect_site_config 自动探测覆盖用户意图。
        # 参考 _cache_user_specified 的成熟模式。
        self._allow_xmlrpc_user_specified = any(
            a == '--allow-xmlrpc' for a in sys.argv[1:])
        self._optimize_user_specified = any(
            a == '--optimize' for a in sys.argv[1:])
        self._cloudflare_user_specified = any(
            a == '--cloudflare' for a in sys.argv[1:])
        self._http3_user_specified = any(
            a == '--http3' for a in sys.argv[1:])
        self._redis_user_specified = any(
            a == '--redis' for a in sys.argv[1:])
        # [PATCH-192 D7] --no-* 反向开关: 显式禁用功能, 阻止自动探测覆盖
        self._redis_user_disabled = any(
            a == '--no-redis' for a in sys.argv[1:])
        self._optimize_user_disabled = any(
            a == '--no-optimize' for a in sys.argv[1:])
        self._cloudflare_user_disabled = any(
            a == '--no-cloudflare' for a in sys.argv[1:])
        self._http3_user_disabled = any(
            a == '--no-http3' for a in sys.argv[1:])
        self._allow_xmlrpc_user_disabled = any(
            a == '--no-allow-xmlrpc' for a in sys.argv[1:])

        # [PATCH] SSL 可选: --skip-ssl 跳过证书签发, 仅部署 HTTP 站点
        self.skip_ssl = getattr(args, 'skip_ssl', False)

        # [V3.2.52] ZeroSSL EAB 凭据 (可选备用 CA)
        # 优先级: CLI 参数 > 环境变量 WP_ZEROSSL_EAB_KID / WP_ZEROSSL_EAB_HMAC_KEY
        # [PATCH-201 C] argparse default 已通过 os.environ.get 预捕获环境变量,
        # SEC-03 在 argparse 之后、SiteConfig 之前删除了 WP_ZEROSSL_EAB_KID /
        # WP_ZEROSSL_EAB_HMAC_KEY, 此处 os.environ.get 恒返回空串, 属死代码。
        # 移除冗余回退, 仅从 args 读取。
    # [PATCH-195 FIX-7] 注意: default=os.environ.get(...) 在
    # add_argument() 时立即求值, SEC-03 在 parse_args() 之后删除
    # 环境变量不影响已捕获值。勿将 default= 改为运行时读取。
        self.zerossl_eab_kid = (
            getattr(args, 'zerossl_eab_kid', None) or ''
        ).strip()
        self.zerossl_eab_hmac_key = (
            getattr(args, 'zerossl_eab_hmac_key', None) or ''
        ).strip()
        # 两者必须同时提供才有效；单独提供一个给出警告
        if bool(self.zerossl_eab_kid) != bool(self.zerossl_eab_hmac_key):
            logging.warning(t("warn_zerossl_eab_mismatch"))
            self.zerossl_eab_kid = ""
            self.zerossl_eab_hmac_key = ""


        # [V3.2.79] 失败通知 webhook + 操作前备份开关
        self.notify_webhook = (
            getattr(args, 'notify_webhook', '') or
            os.environ.get('WP_NOTIFY_WEBHOOK', '')
        ).strip()
        self.no_pre_backup = getattr(args, 'no_pre_backup', False)

        # [V3.2.21-AUDIT] P2-5: --no-db-ssl 禁用外置数据库 SSL 连接
        # None = 自动 (外置 DB 默认启用); False = 显式禁用
        self.db_ssl = False if getattr(args, 'no_db_ssl', False) else None


        # [V3.0.4] 备份根目录：CLI --backup-dir > 环境变量 WP_BACKUP_DIR > 默认 /root/backups
        # 允许用户将备份写入外挂数据盘（如 /data/backups），对开源部署场景更友好。
        _cli_backup_dir  = getattr(args, 'backup_dir', None) or ''
        _env_backup_dir  = os.environ.get('WP_BACKUP_DIR', '').strip()
        _backup_base_raw = _cli_backup_dir or _env_backup_dir or '/root/backups'
        # [PATCH-252 FIX-10] 安全校验: 拒绝系统关键目录作为备份根目录。
        # 备份的 --keep 清理逻辑 (_backup_verify_and_cleanup) 会
        # shutil.rmtree 删除旧备份子目录; 若 backup_base_dir 指向 /etc
        # 等系统目录, 子目录可能是系统配置, 被误删导致灾难。
        # 另外 atomic_write 的 TOCTOU 防护假设目标路径不在用户可控
        # 目录中, backup_base_dir 可通过 CLI/环境变量任意设定,
        # 需在此处收窄攻击面。
        _backup_resolved_252 = os.path.realpath(_backup_base_raw)
        _FORBIDDEN_BACKUP_DIRS_252 = frozenset((
            '/', '/etc', '/usr', '/var', '/var/lib', '/boot',
            '/bin', '/sbin', '/lib', '/lib64', '/dev', '/proc',
            '/sys', '/run', '/tmp',
        ))
        # Normalize: strip trailing slashes, but preserve '/' itself
        _bak_norm_252 = _backup_resolved_252.rstrip('/') or '/'
        if _bak_norm_252 in _FORBIDDEN_BACKUP_DIRS_252:
            print(
                "[PATCH-252 FIX-10] Fatal: --backup-dir '%s' (resolved: "
                "'%s') points to a system-critical directory. Backup "
                "cleanup (--keep) could delete essential system files. "
                "Please use a dedicated directory like /root/backups "
                "or /data/backups."
                % (_backup_base_raw, _backup_resolved_252))
            sys.exit(1)
        # Also reject if resolved path IS an existing regular file
        if os.path.isfile(_backup_resolved_252):
            print(
                "[PATCH-252 FIX-10] Fatal: --backup-dir '%s' points to "
                "an existing file, not a directory."
                % _backup_base_raw)
            sys.exit(1)
        self.backup_base_dir = Path(_backup_base_raw)



        # [PATCH-201 C] argparse default 已通过 os.environ.get 预捕获 WP_DB_ROOT_PASS,
        # SEC-03 在 SiteConfig 初始化前已删除该环境变量。移除冗余回退。
    # [PATCH-195 FIX-7] 注意: default=os.environ.get(...) 在
    # add_argument() 时立即求值, SEC-03 在 parse_args() 之后删除
    # 环境变量不影响已捕获值。勿将 default= 改为运行时读取。
        _raw_db_root_pass = getattr(args, 'db_root_pass', None)
        # [AUDIT-R5 H-5] 纵深防御: 在 SiteConfig 入口处拦截 NUL 和换行符。
        # _is_safe_password 白名单 [a-zA-Z0-9!@#$%^&*()_+=.-] 已排除这些字符,
        # 但 shell 可传入 $'\n' 等值绕过白名单前的处理阶段。
        # 换行符可截断 MySQL .cnf [client] 段并注入 [mysqld] 等恶意段。
        if _raw_db_root_pass and any(
            c in _raw_db_root_pass for c in ('\x00', '\n', '\r')
        ):
            print("Fatal: --db-root-pass contains NUL or newline characters")
            sys.exit(1)
        self.db_root_pass_input = _raw_db_root_pass
        self.db_host = getattr(args, 'db_host', None) or \
            os.environ.get('WP_DB_HOST') or 'localhost'
        self.persist_root_pwd = getattr(args, 'persist_root_pwd', False)
        # V2.7.1: db_host 白名单校验，防止 SQL 注入与命令注入
        # [V3.2.136] AUDIT S-5 设计约束: 字符集含 [ ] : 用于 IPv6 字面量,
        # db_host 仅用于 MySQL .cnf [client] host= 值 (安全) 和日志输出,
        # 绝不可拼接进 shell 命令字符串 (subprocess 已用列表传参, 无此风险)。
        if not re.fullmatch(r'[a-zA-Z0-9._:\[\]-]+', self.db_host):
            print(t("err_dbhost_fmt", host=self.db_host))
            sys.exit(1)

        # 数据库等待超时：CLI 参数 > 环境变量 WP_DB_WAIT_TIMEOUT > 默认值（函数内决策）
        _cli_timeout = getattr(args, 'db_wait_timeout', None)
        _env_timeout = os.environ.get('WP_DB_WAIT_TIMEOUT', '')
        if _cli_timeout is not None:
            self.db_wait_timeout = int(_cli_timeout)
        elif _env_timeout:
            # [V2.9.5] 使用 try/except 替代 isdigit()，兼容前导 0 等边界输入
            try:
                self.db_wait_timeout = int(_env_timeout)
            except ValueError:
                # [V3.2.98] FIX-C2 (§3.5): 日志系统已初始化, 使用 logging
                logging.warning(t("warn_timeout_env", val=_env_timeout))
                self.db_wait_timeout = None
        else:
            self.db_wait_timeout = None  # 由 _wait_db_ready 根据 is_external_db 决定

        # V2.8.0: 校验超时值为正整数，防止 range() 空迭代跳过等待
        if self.db_wait_timeout is not None and self.db_wait_timeout < 1:
            print(t("err_timeout_val", val=self.db_wait_timeout))
            sys.exit(1)

        # [V3.0.19] D1: certbot 二进制与证书路径在初始化时探测一次，
        # 全局缓存到 self.certbot_bin / self.cert_chain / self.cert_key。
        # 所有下游调用方（apply_cert / renew_cert / setup_nginx 等）直接使用，
        # 消除运行期重复探测，兼容 snap / certbot-auto 非标安装。
        # 首次 deploy 时证书尚未签发：_probe_cert_paths 回退到标准路径，
        # 不影响 apply_cert 等后续流程（调用方各自做 .exists() 检查）。
        self.certbot_bin = self._detect_certbot_bin()
        # [V3.1.1] P4: Cache nginx/systemctl absolute paths
        # Used by _install_certbot_deploy_hook() to generate
        # shell hooks with runtime-detected paths instead of
        # hardcoded /usr/sbin/nginx or /bin/systemctl.
        self.nginx_bin = shutil.which("nginx") or "/usr/sbin/nginx"
        self.systemctl_bin = shutil.which("systemctl") or "/bin/systemctl"
        # [V3.1.1] P7: Cache mysqlcheck absolute path
        # setup_db_optimize_timer() writes this into ExecStart of the
        # systemd service unit instead of relying on bare 'mysqlcheck',
        # which may not be on the narrow default PATH of systemd units.
        # Fallback mirrors common distro locations (/usr/bin is safest).
        self.mysqlcheck_bin = (
            shutil.which("mysqlcheck") or "/usr/bin/mysqlcheck"
        )
        self.cert_chain, self.cert_key = self._probe_cert_paths(
            self.domain, self.certbot_bin
        )

        # ── [PATCH-221] 加载 clean 快照, 自动恢复缺省配置 ─────────
        # 仅在 deploy 子命令时生效, 且仅覆盖用户未显式指定的参数。
        # 快照由 _clean_uninstall_site._save_clean_snapshot 创建。
        _is_deploy_cmd = (len(sys.argv) > 1 and sys.argv[1] == "deploy")
        if _is_deploy_cmd:
            _snap = _load_clean_snapshot(self.domain, sanitized_id
                if len(sanitized_id) <= 48
                else sanitized_id[:40] + "_" + _md5_noncrypto(
                    sanitized_id.encode()).hexdigest()[:7])
            if _snap:
                _restored_opts = []
                # cache_mode: 仅当用户未通过 --cache 显式指定时恢复
                if (self.cache_mode == "none"
                        and _snap.get("cache", "none") != "none"
                        and not self._cache_user_specified):
                    _snap_cache_244 = _snap["cache"]
                    # [PATCH-244] 快照恢复 cache=redis 时验证 Nginx 版本。
                    # 若 Nginx < _NGINX_MIN_VERSION, srcache 编译必然 ABI 崩溃后降级为
                    # fastcgi, 浪费 ~40 秒且导致 FPM 不稳定。提前拦截。
                    if _snap_cache_244 == "redis":
                        _nv_snap_244 = _get_nginx_version_tuple()
                        if (_nv_snap_244 != (0, 0, 0)
                                and _nv_snap_244 < _NGINX_MIN_VERSION):
                            _snap_cache_244 = "fastcgi"
                            logging.info(t("info_snap_cache_downgrade_nginx",
                                           ver="%d.%d.%d" % _nv_snap_244))
                    self.cache_mode = _snap_cache_244
                    _restored_opts.append("cache=%s" % self.cache_mode)
                # bool 选项: 仅当用户未显式指定时恢复
                _SNAP_BOOL_MAP = [
                    ("redis", "redis_cache", "_redis_user_specified",
                     "_redis_user_disabled"),
                    ("optimize", "optimize", "_optimize_user_specified",
                     "_optimize_user_disabled"),
                    ("cloudflare", "cloudflare", "_cloudflare_user_specified",
                     "_cloudflare_user_disabled"),
                    ("http3", "http3", "_http3_user_specified",
                     "_http3_user_disabled"),
                    ("allow_xmlrpc", "allow_xmlrpc",
                     "_allow_xmlrpc_user_specified",
                     "_allow_xmlrpc_user_disabled"),
                ]
                for _sk, _attr, _spec, _dis in _SNAP_BOOL_MAP:
                    if (_snap.get(_sk, False)
                            and not getattr(self, _attr)
                            and not getattr(self, _spec, False)
                            and not getattr(self, _dis, False)):
                        setattr(self, _attr, True)
                        _restored_opts.append(_sk)
                # wp_auto_install
                if (_snap.get("wp_auto_install", False)
                        and not self.wp_auto_install):
                    self.wp_auto_install = True
                    _restored_opts.append("wp_auto_install")
                # persist_root_pwd
                if (_snap.get("persist_root_pwd", False)
                        and not self.persist_root_pwd):
                    self.persist_root_pwd = True
                    _restored_opts.append("persist_root_pwd")
                # email (仅当 CLI 未提供)
                # [PATCH-239 FIX-8] Apply SiteConfig-equivalent email
                # format validation. Previous code accepted email from
                # snapshot without the regex check that __init__ (L4012)
                # and setup_systemd (L17411) both enforce. A tampered
                # snapshot could inject a malicious email into certbot
                # command line via _sd_escape in systemd ExecStart.
                if (_snap.get("email") and not self.email):
                    _snap_email_239 = str(_snap["email"]).lower().strip()
                    if (
                        _snap_email_239
                        and len(_snap_email_239) <= 254
                        and re.match(
                            r'^[a-z0-9._%+\-]+@[a-z0-9]([a-z0-9.-]*[a-z0-9])?\.[a-z]{2,}$',
                            _snap_email_239)
                        and '..' not in _snap_email_239
                    ):
                        self.email = _snap_email_239
                        _restored_opts.append("email")
                    else:
                        logging.warning(
                            "[PATCH-239 FIX-8] Snapshot email '%s' "
                            "failed format validation; discarded.",
                            str(_snap.get("email", ""))[:50])
                # notify_webhook
                # [PATCH-239 FIX-8] Apply _validate_webhook_url check
                # consistent with setup_systemd (L17444). Previous code
                # accepted webhook URL without any security validation.
                if (_snap.get("notify_webhook")
                        and not self.notify_webhook):
                    _snap_wh_239 = str(_snap["notify_webhook"]).strip()
                    if WPDeployManager._validate_webhook_url(_snap_wh_239):
                        self.notify_webhook = _snap_wh_239
                        _restored_opts.append("notify_webhook")
                    else:
                        logging.warning(t("warn_patch_239_fix_8_snapshot_webhook_url_failed_securit"))
                # ZeroSSL EAB
                if (_snap.get("zerossl_eab_kid")
                        and not self.zerossl_eab_kid
                        and _snap.get("zerossl_eab_hmac_key")
                        and not self.zerossl_eab_hmac_key):
                    self.zerossl_eab_kid = _snap["zerossl_eab_kid"]
                    self.zerossl_eab_hmac_key = _snap["zerossl_eab_hmac_key"]
                    _restored_opts.append("zerossl_eab")
                if _restored_opts:
                    logging.info(t("info_clean_snapshot_loaded",
                                   opts=", ".join(_restored_opts)))


    @property
    def credentials_file(self) -> Path:
        """凭据文件路径。[PATCH-146 P2-5]"""
        return Path(f"/root/.wp_credentials_{self.systemd_prefix}.txt")

    @property
    def le_live_dir(self) -> Path:
        """LE live 证书目录。[PATCH-146 P3-2]"""
        return Path(f"/etc/letsencrypt/live/{self.domain}")

    @property
    def le_archive_dir(self) -> Path:
        """LE archive 目录。[PATCH-146 P3-2]"""
        return Path(f"/etc/letsencrypt/archive/{self.domain}")

    @property
    def le_renewal_conf(self) -> Path:
        """LE renewal 配置。[PATCH-146 P3-2]"""
        return Path(f"/etc/letsencrypt/renewal/{self.domain}.conf")

    @property
    def is_external_db(self) -> bool:
        """判断是否使用外置数据库（非本机）。

        [V3.2.3] L-5: 扩展本地别名覆盖, 包含 localhost.localdomain 等。
        [V3.2.13] P1-3: 兼容 host:port 和 [IPv6]:port 格式。
        """
        _h = self.db_host
        # Strip port suffix: [::1]:3306 → ::1, 127.0.0.1:3306 → 127.0.0.1
        if _h.startswith("["):
            _end = _h.find("]")
            if _end > 0:
                _h = _h[1:_end]
        else:
            _parts = _h.rsplit(":", 1)
            if len(_parts) == 2 and _parts[1].isdigit() and ":" not in _parts[0]:
                _h = _parts[0]
        _local_hosts = (
            'localhost', '127.0.0.1', '::1',
            'localhost.localdomain', 'localhost4', 'localhost6',
            'ip6-localhost', 'ip6-loopback',
        )
        return _h not in _local_hosts

    @staticmethod
    def _detect_certbot_bin() -> str:
        """D1: 探测 certbot 可执行文件的实际路径。

        安装方式优先级:
          1. PATH 中的 certbot          — apt/yum 标准包管理器安装
          2. /snap/bin/certbot          — Ubuntu Snap 安装
             (Snap 经常不在 root 的 PATH 中，必须显式探测)
          3. /opt/certbot/bin/certbot   — EFF pip venv 安装
             (symlink /usr/local/bin/certbot 可能被删除/覆盖，必须显式探测)
          4. /usr/local/bin/certbot-auto — 旧版 certbot-auto 独立安装
          5. 'certbot'                   — 兜底；不在 PATH 时 run_cmd
             返回 FATAL CmdResult，错误信息清晰可查。
        """
        # 优先级 1: PATH 中的 certbot（apt/yum 标准安装，最常见）
        found = shutil.which("certbot")
        if found:
            return found
        # 优先级 2: Snap 安装路径（Ubuntu 22.04+ 推荐方式，通常不在 root PATH）
        snap_bin = Path("/snap/bin/certbot")
        if snap_bin.is_file():
            return str(snap_bin)
        # 优先级 3: EFF pip venv 安装路径
        # [PATCH-270e] 对齐 snap 的显式探测。symlink /usr/local/bin/certbot
        # 可能被意外删除 (手动操作/包管理器覆盖/snap 迁移失败残留),
        # 此时 shutil.which 找不到 certbot, 但 venv 二进制仍完好。
        pip_venv_bin = Path("/opt/certbot/bin/certbot")
        if pip_venv_bin.is_file():
            return str(pip_venv_bin)
        # 优先级 4: certbot-auto 传统独立安装
        certbot_auto = Path("/usr/local/bin/certbot-auto")
        if certbot_auto.is_file():
            return str(certbot_auto)
        # 优先级 5: 兜底（依赖运行时 PATH，不在 PATH 则 run_cmd 会 FATAL）
        return "certbot"

    @staticmethod
    def _probe_cert_paths(domain: str, certbot_bin: str) -> tuple:
        """D1: 在 SiteConfig 初始化时探测证书文件的实际路径。

        返回 (cert_chain: Path, cert_key: Path)。

        探测策略:
          1. 标准路径 /etc/letsencrypt/live/{domain}/fullchain.pem 已存在
             → 直接返回（最快路径，覆盖续期 / 状态查询等高频场景）。
          2. `certbot_bin certificates --domain {domain}` 解析
             'Certificate Path:' 行，兼容 certbot-auto / snap 自定义目录。
          3. 以上均未命中（首次 deploy，证书尚未签发）
             → 返回标准路径（调用方负责 .exists() 检查）。

        此方法不阻塞: certbot 探测超时 5 s，任何异常静默处理。
        """
        std_dir   = Path(f"/etc/letsencrypt/live/{domain}")
        std_chain = std_dir / "fullchain.pem"
        std_key   = std_dir / "privkey.pem"

        # 优先级 1: 标准路径存在（续期 / status 等最常见场景，无额外开销）
        if std_chain.exists():
            return (std_chain, std_key)

        # 优先级 2: certbot certificates 探测（snap / certbot-auto 非标路径）
        try:
            r = subprocess.run(
                [certbot_bin, "certificates", "--domain", domain],
                stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                encoding='utf-8', errors='replace', timeout=5, check=False,
            )
            if r.returncode == 0:
                for line in r.stdout.splitlines():
                    line = line.strip()
                    if line.startswith("Certificate Path:"):
                        _cp_parts = line.split(":", 1)  # [PATCH-283 FIX-P2-1b]
                        cert_path = Path(_cp_parts[1].strip()) if len(_cp_parts) > 1 else None
                        if cert_path is not None and cert_path.exists():
                            return (cert_path, cert_path.parent / "privkey.pem")
        except Exception as _exc_8036:
            logging.warning("[PATCH-276] stdout: %s", _exc_8036)

        # 优先级 3: 回退到标准路径（首次 deploy / 探测失败）
        return (std_chain, std_key)

    @staticmethod
    def _detect_webroot_base() -> str:
        """根据发行版选择 Nginx 站点根目录基准路径。
        Debian/Ubuntu: /var/www/html  (apt 体系惯例)
        RHEL/CentOS:   /usr/share/nginx/html  (yum/dnf 体系惯例)

        V2.8.0: 优先从 /etc/os-release 识别发行版族系，
        避免安装了 apt 的非 Debian 系统（如 Arch）误判"""
        # 优先级 1: /etc/os-release（最可靠的发行版标识）
        try:
            _osr = Path('/etc/os-release').read_text(encoding='utf-8').lower()
            # ID_LIKE 包含 debian 的衍生版（Ubuntu/Mint/Deepin）
            if 'id_like' in _osr:
                _like = re.search(r'^id_like\s*=\s*"?([^"\n]+)', _osr, re.MULTILINE)
                if _like and 'debian' in _like.group(1):
                    return "/var/www/html"
                if _like and any(d in _like.group(1) for d in ('rhel', 'fedora', 'centos')):
                    return "/usr/share/nginx/html"
            # 直接匹配 ID
            _id = re.search(r'^id\s*=\s*"?([^"\n]+)', _osr, re.MULTILINE)
            if _id:
                _id_val = _id.group(1).strip()
                if _id_val in ('debian', 'ubuntu', 'linuxmint', 'deepin', 'pop', 'kali'):
                    return "/var/www/html"
        except Exception as _exc_8066:
            logging.debug("[PATCH-276] _osr: %s", _exc_8066)
        # 优先级 2: 包管理器探测（回退）
        if shutil.which("apt"):
            return "/var/www/html"
        return "/usr/share/nginx/html"

    @staticmethod
    def validate_sql_identifier(name: str) -> bool:
        """校验数据库名/用户名：仅允许字母、数字、下划线，防止 SQL 注入"""
        return bool(re.fullmatch(r'[a-zA-Z0-9_]+', name))

    @staticmethod
    def validate_sql_password(password: str) -> bool:
        """校验自动生成的数据库密码：严格纯字母数字字符集。

        [V3.2.101] P2-4 scope clarification:
        此方法仅用于校验 secrets.choice() 自动生成的密码 ([a-zA-Z0-9])。
        从 wp-config.php 恢复的旧密码使用更宽松的白名单
        ([a-zA-Z0-9!@#$%^&*()_+=.-]+), 由 _recover_existing_db_pass()
        独立校验, 不经此方法。两者白名单差异是有意设计。
        """
        return bool(re.fullmatch(r'[a-zA-Z0-9]+', password))

